import 'dart:convert';
import 'dart:io';
void main(List<String> args){final pid=args.single;final r=Process.runSync('/bin/ps',['eww','-p',pid,'-o','command=']);final s=r.stdout.toString();final values={for(final key in ['MTL_CAPTURE_ENABLED','SIMCTL_CHILD_MTL_CAPTURE_ENABLED','MTLCAPTURE_WAIT_FOR_SIGNAL'])key:RegExp('(?:^|\\s)$key=([^\\s]+)').firstMatch(s)?.group(1)};final maps=Process.runSync('/usr/bin/vmmap',[pid]);final lines=maps.stdout.toString().split('\n').where((l)=>l.contains('GPUToolsCapture')||l.contains('MTLTools')||l.contains('MetalSim'));final out={'pid':pid,'psExit':r.exitCode,'captureEnvironment':values,'vmmapExit':maps.exitCode,'captureMappings':lines.toList()};print(jsonEncode(out));File('/private/tmp/dart3d-u3-outline-metal-trace-20261028/r1/parent/baseline/capture-readiness.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(out));}
